/***************************************************************************************************** 
 *
 * Serialization is the process of converting a data structure or object into a sequence of bits so 
 * that it can be stored in a file or memory buffer, or transmitted across a network connection link 
 * to be reconstructed later in the same or another computer environment.
 * 
 * Design an algorithm to serialize and deserialize a binary tree. There is no restriction on how your 
 * serialization/deserialization algorithm should work. You just need to ensure that a binary tree can 
 * be serialized to a string and this string can be deserialized to the original tree structure.
 * 
 * Example: 
 * 
 * You may serialize the following tree:
 * 
 *     1
 *    / \
 *   2   3
 *      / \
 *     4   5
 * 
 * as "[1,2,3,null,null,4,5]"
 * 
 * Clarification: The above format is the same as how LeetCode serializes a binary tree. You do not 
 * necessarily need to follow this format, so please be creative and come up with different approaches 
 * yourself.
 * 
 * Note: Do not use class member/global/static variables to store states. Your serialize and 
 * deserialize algorithms should be stateless.
 ******************************************************************************************************/

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) { val = x; }
 * }
 */
public class Codec {

    // Encodes a tree to a single string.
    public String serialize(TreeNode root) {
        if (root == null) {
            return "#_";
        }

        var sb = new StringBuilder();
        sb.append(root.val).append("_");
        sb.append(serialize(root.left));
        sb.append(serialize(root.right));

        return sb.toString();
    }

    // Decodes your encoded data to tree.
    public TreeNode deserialize(String data) {
        // System.out.println(data);

        var queue = new LinkedList<Integer>();
        var arr = data.split("_");
        for (var item : arr) {
            if (item.equals("#")) {
                queue.offer(null);
            } else {
                queue.offer(Integer.parseInt(item));
            }
        }
        // System.out.println(queue);

        return helper(queue);
    }

    TreeNode helper(Queue<Integer> queue) {
        var val = queue.poll();
        if (val == null) {
            return null;
        }

        var cur = new TreeNode(val);
        cur.left = helper(queue);
        cur.right = helper(queue);
        return cur;
    }
}

